sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	if (current.category == 'Access') {

        // Priority 2 usually corresponds to 'High' in ServiceNow out-of-the-box
        // (1: Critical, 2: High, 3: Moderate, 4: Low)
        current.priority = 20; 
    }

})(current, previous);
